entries[393059] = { ["name"] = "Thousandbite Piranha", ["text"] = "5 yd range\n3.2 sec cast\nThousandbite Piranha are an aggressive freshwater fish that will devour anything in sight!\n\nThese freshwater swarms are found primarily in vast lakes and sprawling river systems across the Dragon Isles.\n\nThey are especially active in areas such as The Ohn'ahran Plains and The Waking Shores." }
entries[393060] = { ["name"] = "Cerulean Spinefish", ["text"] = "5 yd range\n3.2 sec cast\nCerulean Spinefish are a sturdy fish adorned with many sharp spines.\n\nThese saltwater schools can be found primarily in the ocean and other bodies of water connected to it.\n\nThey are especially active in areas such as the river openings around The Waking Shores." }
entries[393061] = { ["name"] = "Aileron Seamoth", ["text"] = "5 yd range\n3.2 sec cast\nAileron Seamoth glide across the ocean floor and jet upwards when they suspect a tasty treat!\n\nThese saltwater schools can be found primarily in the ocean and other bodies of water connected to it.\n\nThey are especially active in areas such as Iskaara in The Azure Span." }
entries[393062] = { ["name"] = "Temporal Dragonhead", ["text"] = "5 yd range\n3.2 sec cast\nTemporal Dragonhead are a peculiar fish whose scales seem to displace forwards and backwards every few seconds. Keep your fingers away from their sharp snout!\n\nThese freshwater schools can be found primarily in the vast lakes and sprawling river systems around the Dragon Isles.\n\nThey are especially active in areas such as the Uktulut Backwater in The Waking Shores." }
entries[393063] = { ["name"] = "Scalebelly Mackerel", ["text"] = "5 yd range\n3.2 sec cast\nScalebelly Mackerel are an incredibly common fish in the Dragon Isles. They are easily caught in all bodies of water.\n\nTossing unused Scalebelly Mackerel back into the water is a routine exercise done by even the most experienced Anglers." }
entries[393064] = { ["name"] = "Islefin Dorado", ["text"] = "5 yd range\n3.2 sec cast\nIslefin Dorado are an elusive fish whose fin is said to resemble the Dragon isles.\n\nThey are found in all bodies of water around the isles." }
entries[393065] = { ["name"] = "Shimmering Treasure", ["text"] = "5 yd range\n3.2 sec cast\nShimmering Treasure can appear in all bodies of water across the Dragon Isles. These pools contain untold treasures and are what every angler hopes to stumble upon.\n\nFishing in these pools significantly increases your chance for rare treasures." }
entries[393066] = { ["name"] = "Rimefin Tuna", ["text"] = "5 yd range\n3.2 sec cast\nRimefin Tuna are a large, fatty fish coated in a thin layer of protective ice. The thick layer of fat protects their vital organs in below freezing temperatures.\n\nYou can find these pools in especially frosty climates around the Dragon Isles.\n\nThe Iskaara Tuskarr are experts in catching these kinds of special fish." }
entries[393067] = { ["name"] = "Magma Thresherl", ["text"] = "5 yd range\n3.2 sec cast\nMagma Threshers are a muscular fish with a hardened outer shell consisting of various minerals.\n\nYou can find these pools in especially hot climates around the Dragon Isles.\n\nThe Iskaara Tuskarr are experts in catching these kinds of special fish." }
